      SUBROUTINE SOLGETCC     GET PARAMETERS DESCRIBING SOLENOIDCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM19.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'XRAN.CIN'C      INTEGER         IADR, IB, IDATA, IK, IT      REAL            DATAR, DEN      EXTERNAL        DATAR, IDATAC      IADR = I + 1      L = DATAR(IADR)      IF (PRAN19(1) .NE. 0.0) L = L + PRAN19(1)*XRAN(1)      L = L*UNITI(8)C      IB = IPTOJ(2)      IK = IPTOJ(3)      IF (IK .NE. 0) GO TO 5      IADR = I + IB      B = DATAR(IADR)      IF (PRAN19(2) .NE. 0.0) B = B + PRAN19(2)*XRAN(2)      B = B*UNITI(9)*RI/PREF      IF (NORD1 .LT. 1) GO TO 10      KO = DEN(B/RI)      KL = KO*L      GO TO 10C    5 IADR = I + IK      KL = DATAR(IADR)      IF (PRAN19(3) .NE. 0.0)     1    KL = KL + PRAN19(3)*XRAN(3)      KL = 2.0*KL*UNITI(13)      KO = KL/LC   10 IT = IPTOJ(4)      IF (IT .EQ. 0) THEN        NUMTYP = IT      ELSE        NUMTYP = IDATA(I + IT)      ENDIF      RETURN      END